  function quiet(){audioEpoch++;clearTimeout(musicTimer);musicTimer=null;if(audio&&master){master.gain.cancelScheduledValues(audio.currentTime);master.gain.setTargetAtTime(0,audio.currentTime,.025);bed.gain.setTargetAtTime(0,audio.currentTime,.025);water?.gain.setTargetAtTime(0,audio.currentTime,.025)}}
  function music(){if(!soundOn||!audio||!visible||document.hidden||userPaused){musicTimer=null;return}const melody=[523.25,659.25,783.99,880,783.99,659.25,587.33,0,523.25,659.25,783.99,1046.5,880,783.99,659.25,0,698.46,880,1046.5,880,783.99,698.46,659.25,0,587.33,783.99,880,783.99,659.25,587.33,523.25,0];const step=musicStep++%melody.length,now=audio.currentTime+.015;if(melody[step])mallet(melody[step],now,step%2?.065:.085);if(step%4===0){const bass=[130.81,130.81,174.61,196][Math.floor(step/8)];mallet(bass,now,.045,bed,1);mallet(bass*2,now+.07,.025,bed,.8)}musicTimer=setTimeout(music,340)}
  function ambient(){if(!soundOn||!audio)return;audio.resume().catch(()=>{});master.gain.setTargetAtTime(volume,audio.currentTime,.08);bed.gain.setTargetAtTime(.65,audio.currentTime,.08);water.gain.setTargetAtTime(.035,audio.currentTime,.3);if(!musicTimer)music()}
  function turnSound(){const states=rules.map(r=>state(r,frame));return states.includes('issue')?'issue':frame===19&&states.includes('recovered')?'recovered':states.every(s=>s==='unknown')?'unknown':'pass'}
  async function cue(kind){if(!soundOn||!visible||document.hidden||!audio)return;const epoch=audioEpoch;try{await audio.resume()}catch{return}if(epoch!==audioEpoch||!soundOn||!visible||document.hidden)return;master.gain.setTargetAtTime(volume,audio.currentTime,.02);const notes=kind==='issue'?[659.25,587.33]:kind==='recovered'?[523.25,659.25,783.99,1046.5]:kind==='unknown'?[440]:[frame%2?783.99:659.25];notes.forEach((f,i)=>mallet(f,audio.currentTime+i*.13,kind==='recovered'?.09:.055,master,.4))}
  function pause(explicit=false){quiet();clearTimeout(timer);timer=null;if(explicit)userPaused=true;document.querySelector('#intro-play')?.replaceChildren(document.createTextNode('▷ Play story'));document.querySelector('#garden-stage')?.classList.remove('playing');}
