    document.querySelector('#garden-author').onsubmit=e=>{e.preventDefault();const text=document.querySelector('#garden-new-rule').value.trim();if(!text)return;pause(true);definitions.custom={name:'Custom criterion',rule:text};if(!rules.includes('custom'))rules.push('custom');selected=rules.indexOf('custom');document.querySelector('.garden-layout').classList.add('inspecting');world();paint()};
